"""Regression tests for the crd2pulumi provider-default post-processing."""

from __future__ import annotations

from pathlib import Path
import runpy
import subprocess
import sys

import pytest


_REPO_ROOT = Path(__file__).resolve().parents[3]
_PATCHER = runpy.run_path(
    str(_REPO_ROOT / "scripts/patch_crd_sdk_provider_defaults.py")
)
Target = _PATCHER["Target"]
TARGETS = _PATCHER["TARGETS"]
patch_source = _PATCHER["patch_source"]

_GENERATED_SOURCE = """\
# coding=utf-8
# *** WARNING: this file was generated by crd2pulumi. ***
# *** Do not edit by hand unless you're certain you know what you are doing! ***

import pulumi

def get_resource_opts_defaults() -> pulumi.ResourceOptions:
    return pulumi.ResourceOptions(
        version=get_version(),
        plugin_download_url=get_plugin_download_url(),
    )

def get_invoke_opts_defaults() -> pulumi.InvokeOptions:
    return pulumi.InvokeOptions(
        version=get_version(),
        plugin_download_url=get_plugin_download_url(),
    )
"""


def _target() -> object:
    return Target(
        relative_path=Path("sdk/_utilities.py"),
        package_name="example-crds",
        example_token="kubernetes:example.io/v1:Example",
        plugin_name="pulumi-resource-example-crds",
    )


def test_patches_generated_provider_defaults_idempotently() -> None:
    patched = patch_source(_GENERATED_SOURCE, _target())

    assert "version=get_version()" not in patched
    assert "plugin_download_url=get_plugin_download_url()" not in patched
    assert "return pulumi.ResourceOptions()" in patched
    assert "return pulumi.InvokeOptions()" in patched
    assert patch_source(patched, _target()) == patched


def test_command_patches_generated_sdk_tree(tmp_path: Path) -> None:
    for target in TARGETS:
        path = tmp_path / target.relative_path
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(_GENERATED_SOURCE, encoding="utf-8")

    command = [
        sys.executable,
        str(_REPO_ROOT / "scripts/patch_crd_sdk_provider_defaults.py"),
        "--root",
        str(tmp_path),
    ]

    before = subprocess.run(
        [*command, "--check"], capture_output=True, check=False, text=True
    )
    assert before.returncode == 1
    assert before.stderr.count("needs patch:") == len(TARGETS)

    subprocess.run(command, check=True)
    subprocess.run([*command, "--check"], check=True)


def test_command_can_patch_one_sdk(tmp_path: Path) -> None:
    selected = TARGETS[0]
    path = tmp_path / selected.relative_path
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(_GENERATED_SOURCE, encoding="utf-8")

    subprocess.run(
        [
            sys.executable,
            str(_REPO_ROOT / "scripts/patch_crd_sdk_provider_defaults.py"),
            "--root",
            str(tmp_path),
            "--target",
            "capi-core",
        ],
        check=True,
    )

    assert patch_source(path.read_text(encoding="utf-8"), selected) == (
        path.read_text(encoding="utf-8")
    )


def test_committed_sdk_provider_defaults_are_canonical() -> None:
    for target in TARGETS:
        path = _REPO_ROOT / target.relative_path
        source = path.read_text(encoding="utf-8")

        assert patch_source(source, target) == source, (
            f"{target.relative_path} needs "
            "scripts/patch_crd_sdk_provider_defaults.py"
        )


def test_rejects_unrecognized_generated_structure() -> None:
    source = _GENERATED_SOURCE.replace("generated by crd2pulumi", "generated")

    with pytest.raises(ValueError, match="generated-file marker"):
        patch_source(source, _target())